SELECT * FROM custom_wrong_question
WHERE user_id = #{userId}
ORDER BY last_wrong_time DESC

SELECT cwq.* FROM custom_wrong_question cwq
INNER JOIN custom_question cq ON cwq.question_id = cq.id
WHERE cwq.user_id = #{userId}
  AND cq.is_deleted = 0

  AND cq.category_id = #{categoryId}

ORDER BY cwq.last_wrong_time DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM custom_wrong_question cwq
INNER JOIN custom_question cq ON cwq.question_id = cq.id
WHERE cwq.user_id = #{userId}
  AND cq.is_deleted = 0

  AND cq.category_id = #{categoryId}

mapper.update:
UPDATE custom_wrong_question
SET wrong_times = #{wrongTimes}, user_answer = #{userAnswer}, last_wrong_time = #{lastWrongTime}
WHERE id = #{id}
